import{_ as a,o,c as r,ao as n}from"./chunks/framework.gdZ2Cz2K.js";const p=JSON.parse('{"title":"Citing","description":"","frontmatter":{},"headers":[],"relativePath":"citing.md","filePath":"citing.md","lastUpdated":null}'),i={name:"citing.md"};function t(s,e,c,d,l,h){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="Citing" tabindex="-1">Citing <a class="header-anchor" href="#Citing" aria-label="Permalink to &quot;Citing {#Citing}&quot;">​</a></h1><p>AtmosphericAbsorption.jl makes HITRAN data easy to use, so it is easy to forget that the spectroscopic parameters behind every line-by-line cross-section come from the <a href="https://hitran.org" target="_blank" rel="noreferrer">HITRAN database</a>. If you publish results computed with HITRAN data through this package, <strong>please cite the HITRAN edition you used</strong> (and HAPI where noted below).</p><h2 id="Which-edition-did-I-use?" tabindex="-1">Which edition did I use? <a class="header-anchor" href="#Which-edition-did-I-use?" aria-label="Permalink to &quot;Which edition did I use? {#Which-edition-did-I-use?}&quot;">​</a></h2><ul><li><p><strong>Direct downloads</strong> (<code>load_hitran</code>, <code>fetch_hitran</code>, <code>HitranPort(; edition)</code>, <code>load_hitran_nonvoigt</code>): hitran.org serves only the <em>current</em> edition, which is <strong>HITRAN2024</strong> at the time of writing. The <code>edition</code> keyword is a cache/provenance label; it does not select an older edition from the server.</p></li><li><p><strong>Local <code>.par</code> files</strong> (<code>HitranPort(&quot;file.par&quot;; edition)</code>): cite the edition the file came from. Set the <code>edition</code> keyword to match so the provenance record is accurate.</p></li><li><p>Each cached download has a <code>.meta.toml</code> sidecar recording the edition label, spectral window, source URL, SHA-256 checksum, and download date (see <a href="/AtmosphericAbsorption.jl/dev/data_sources#provenance-and-reproducibility">Provenance and reproducibility</a>). Use it to confirm which data a result was computed from.</p></li></ul><h2 id="HITRAN-references" tabindex="-1">HITRAN references <a class="header-anchor" href="#HITRAN-references" aria-label="Permalink to &quot;HITRAN references {#HITRAN-references}&quot;">​</a></h2><p><strong>HITRAN2024</strong></p><p>Gordon IE, Rothman LS, Hargreaves RJ, Gomez FM, Bertin T, Hill C, Kochanov RV, Tan Y, Wcisło P, Makhnev VYu, Bernath PF, Birk M, Boudon V, Campargue A, Coustenis A, Drouin BJ, Gamache RR, Hodges JT, Jacquemart D, Mlawer EJ, Nikitin AV, Perevalov VI, Rotger M, Robert S, Tennyson J, Toon GC, Tran H, Tyuterev VG, Adkins EM, Barbe A, Bailey DM, Bielska K, Bizzocchi L, Blake TA, Bowesman CA, Cacciani P, Čermák P, Császár AG, Denis L, Egbert SC, Egorov O, Ermilov AYu, Fleisher AJ, Fleurbaey H, Foltynowicz A, Furtenbacher T, Germann M, Guest ER, Harrison JJ, Hartmann J-M, Hjältén A, Hu S-M, Huang X, Johnson TJ, Jóźwiak H, Kassi S, Khan MV, Kwabia-Tchana F, Lee TJ, Lisak D, Liu A-W, Lyulin OM, Malarich NA, Manceron L, Marinina AA, Massie ST, Mascio J, Medvedev ES, Meshkov VV, Mellau GCh, Melosso M, Mikhailenko SN, Mondelain D, Müller HSP, O&#39;Donnell M, Owens A, Perrin A, Polyansky OL, Raston PL, Reed ZD, Rey M, Richard C, Rieker GB, Röske C, Sharpe SW, Starikova E, Stolarczyk N, Stolyarov AV, Sung K, Tamassia F, Terragni J, Ushakov VG, Vasilchenko S, Vispoel B, Vodopyanov KL, Wagner G, Wójtewicz S, Yurchenko SN, Zobov NF. The HITRAN2024 molecular spectroscopic database. <em>J Quant Spectrosc Radiat Transf</em> 2026;353:109807. <a href="https://doi.org/10.1016/j.jqsrt.2026.109807" target="_blank" rel="noreferrer">doi:10.1016/j.jqsrt.2026.109807</a></p><p><strong>HITRAN2020</strong></p><p>Gordon IE, Rothman LS, Hargreaves RJ, Hashemi R, Karlovets EV, Skinner FM, Conway EK, Hill C, Kochanov RV, Tan Y, Wcisło P, Finenko AA, Nelson K, Bernath PF, Birk M, Boudon V, Campargue A, Chance KV, Coustenis A, Drouin BJ, Flaud J-M, Gamache RR, Hodges JT, Jacquemart D, Mlawer EJ, Nikitin AV, Perevalov VI, Rotger M, Tennyson J, Toon GC, Tran H, Tyuterev VG, Adkins EM, Baker A, Barbe A, Canè E, Császár AG, Dudaryonok A, Egorov O, Fleisher AJ, Fleurbaey H, Foltynowicz A, Furtenbacher T, Harrison JJ, Hartmann J-M, Horneman V-M, Huang X, Karman T, Karns J, Kassi S, Kleiner I, Kofman V, Kwabia-Tchana F, Lavrentieva NN, Lee TJ, Long DA, Lukashevskaya AA, Lyulin OM, Makhnev VYu, Matt W, Massie ST, Melosso M, Mikhailenko SN, Mondelain D, Müller HSP, Naumenko OV, Perrin A, Polyansky OL, Raddaoui E, Raston PL, Reed ZD, Rey M, Richard C, Tóbiás R, Sadiek I, Schwenke DW, Starikova E, Sung K, Tamassia F, Tashkun SA, Vander Auwera J, Vasilenko IA, Vigasin AA, Villanueva GL, Vispoel B, Wagner G, Yachmenev A, Yurchenko SN. The HITRAN2020 molecular spectroscopic database. <em>J Quant Spectrosc Radiat Transf</em> 2022;277:107949. <a href="https://doi.org/10.1016/j.jqsrt.2021.107949" target="_blank" rel="noreferrer">doi:10.1016/j.jqsrt.2021.107949</a></p><p><strong>HITRAN2016</strong></p><p>Gordon IE, Rothman LS, Hill C, Kochanov RV, Tan Y, Bernath PF, Birk M, Boudon V, Campargue A, Chance KV, Drouin BJ, Flaud J-M, Gamache RR, Hodges JT, Jacquemart D, Perevalov VI, Perrin A, Shine KP, Smith M-AH, Tennyson J, Toon GC, Tran H, Tyuterev VG, Barbe A, Császár AG, Devi VM, Furtenbacher T, Harrison JJ, Hartmann J-M, Jolly A, Johnson TJ, Karman T, Kleiner I, Kyuberis AA, Loos J, Lyulin OM, Massie ST, Mikhailenko SN, Moazzen-Ahmadi N, Müller HSP, Naumenko OV, Nikitin AV, Polyansky OL, Rey M, Rotger M, Sharpe SW, Sung K, Starikova E, Tashkun SA, Vander Auwera J, Wagner G, Wilzewski J, Wcisło P, Yu S, Zak EJ. The HITRAN2016 molecular spectroscopic database. <em>J Quant Spectrosc Radiat Transf</em> 2017;203:3–69. <a href="https://doi.org/10.1016/j.jqsrt.2017.06.038" target="_blank" rel="noreferrer">doi:10.1016/j.jqsrt.2017.06.038</a></p><h2 id="HAPI" tabindex="-1">HAPI <a class="header-anchor" href="#HAPI" aria-label="Permalink to &quot;HAPI {#HAPI}&quot;">​</a></h2><p>The HITRAN Application Programming Interface (HAPI) is the reference implementation this package is validated against. Its <code>pcqsdhc</code> routine is the basis of our speed-dependent and Hartmann–Tran profiles, and non-Voigt parameters are fetched from the HITRANonline API. Please also cite HAPI when you use those profiles or parameters:</p><p>Kochanov RV, Gordon IE, Rothman LS, Wcisło P, Hill C, Wilzewski JS. HITRAN Application Programming Interface (HAPI): A comprehensive approach to working with spectroscopic data. <em>J Quant Spectrosc Radiat Transf</em> 2016;177:15–30. <a href="https://doi.org/10.1016/j.jqsrt.2016.03.005" target="_blank" rel="noreferrer">doi:10.1016/j.jqsrt.2016.03.005</a></p>',14)])])}const A=a(i,[["render",t]]);export{p as __pageData,A as default};
